var PET_ADJ=['豆','奶','小','大','胖','圆','毛','皮','糖','布','雪','芝','黑','白','花','金','银','橙','蓝','跳','懒','乖','萌','酷','旺','咪','汪','肉','团','卷'];
var PET_NOUN=['豆','球','团','饼','包','仔','宝','娃','哥','妹','王','皇','霸','星','丁','蛋','毛','尾','爪','丸','卷','粒','果','饭','茶'];
var FLAV={'dog':['汪','财','帅'],'cat':['喵','咪','主'],'fish':['鱼','泡','鳞'],'bird':['翅','羽','歌'],'rabbit':['兔','耳','蹦']};
function petName(type, rng){
  rng=rng||Math.random;
  var adj=PET_ADJ[Math.floor(rng()*PET_ADJ.length)];
  var noun=PET_NOUN[Math.floor(rng()*PET_NOUN.length)];
  var nm=adj+noun;
  var f=FLAV[(type||'').toLowerCase()];
  if(f&&rng()<0.4){ nm=nm+f[Math.floor(rng()*f.length)]; }
  return nm;
}
function petNameBulk(n, type, rng){ rng=rng||Math.random; var out=[]; for(var i=0;i<(n||10);i++) out.push(petName(type,rng)); return out; }
var EXPORTS={petName:petName, petNameBulk:petNameBulk};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PetNameForgePure = EXPORTS; }
